import React from 'react';
import { useProgressTrackerContext } from '../../../../ProgressTrackerContext';
import { useStepContext } from '../Step/StepContext';
import { StyledHeadingLabel, StyledLabel } from './StepLabel.styles';
import { StepLabelProps } from './StepLabel.types';

const StepLabel = ({ label, detail, alertMessage }: StepLabelProps): JSX.Element => {
  const stepContext = useStepContext();
  const progressTrackerContext = useProgressTrackerContext();

  if (!progressTrackerContext || !stepContext) {
    // eslint-disable-next-line no-console
    console.warn(
      'Make sure of ProgressTracker.StepLabel component is subcomponent of ProgressTracker.Step, ProgressTracker.Header and ProgressTracker.Root.'
    );
    return <></>;
  }

  const { error, index } = stepContext;
  const { size, orientation } = progressTrackerContext;

  return (
    <>
      <StyledHeadingLabel
        tabIndex={0}
        aria-label={`Step ${index} header text: ${label}`}
        orientation={orientation}
        size={size}
      >
        {label}
      </StyledHeadingLabel>
      <StyledLabel
        tabIndex={0}
        aria-label={`Step ${index} detail text: ${detail}`}
        size={size}
        orientation={orientation}
      >
        {detail}
      </StyledLabel>
      {error && alertMessage && (
        <StyledLabel
          tabIndex={0}
          aria-label={`Step ${index} alert message: ${alertMessage}`}
          error
          orientation={orientation}
          size={size}
        >
          {alertMessage}
        </StyledLabel>
      )}
    </>
  );
};

export default StepLabel;
